def is_black(r, c):
    # Assuming (1, 1) is white, then (r, c) is black if r+c is odd.
    return (r + c) % 2 != 0

def get_black_squares(N, M):
    S_black = set()
    for r in range(1, N + 1):
        for c in range(1, M + 1):
            if is_black(r, c):
                S_black.add((r, c))
    return S_black

def is_queen_attack(q_r, q_c, target_r, target_c):
    # Queen attacks horizontally, vertically, or diagonally
    if q_r == target_r or q_c == target_c:
        return True
    if abs(q_r - target_r) == abs(q_c - target_c):
        return True
    return False

def calculate_max_reduction(N=6, M=6):
    S_i_plus_1 = get_black_squares(N, M)
    max_l = 0

    print(f"Total candidate squares (|S_i+1|): {len(S_i_plus_1)}")

    # Queenie must place on an empty square. In this setup, S_i_plus_1 are the available empty squares (Black).
    # We iterate through all possible placements q in S_i_plus_1
    for q_r, q_c in S_i_plus_1:
        attacked_count = 0

        # Count how many other squares in S_i_plus_1 are attacked by the queen at (q_r, q_c)
        for r_target, c_target in S_i_plus_1:
            if (r_target, c_target) != (q_r, q_c):
                if is_queen_attack(q_r, q_c, r_target, c_target):
                    attacked_count += 1

        if attacked_count > max_l:
            max_l = attacked_count

    return max_l

max_L = calculate_max_reduction()
print(f"Maximum achievable reduction factor (L_bar): {max_L}")

